# -*- coding: utf-8 -*-
# Fix: renvoie tous les fichiers utilitaires backend par securite (recurrence.ts
# manquait, notamment WEEKLY_COUNT/computeWeeklyDueDone/weekStart)
import pathlib

FILES = {}

FILES['backend/src/lib/prisma.ts'] = 'import { PrismaClient } from "@prisma/client";\n\n// Instance unique du client Prisma, reutilisee partout dans l\'app\nexport const prisma = new PrismaClient();\n'
FILES['backend/src/middleware/auth.ts'] = 'import { Request, Response, NextFunction } from "express";\nimport jwt from "jsonwebtoken";\n\nexport interface AuthRequest extends Request {\n  userId?: string;\n}\n\n// Vérifie le token JWT envoye dans le header "Authorization: Bearer <token>"\n// et attache l\'id utilisateur a la requete si valide.\nexport function requireAuth(req: AuthRequest, res: Response, next: NextFunction) {\n  const header = req.headers.authorization;\n  if (!header || !header.startsWith("Bearer ")) {\n    return res.status(401).json({ error: "Authentification requise." });\n  }\n\n  const token = header.slice("Bearer ".length);\n  try {\n    const secret = process.env.JWT_SECRET as string;\n    const payload = jwt.verify(token, secret) as { userId: string };\n    req.userId = payload.userId;\n    next();\n  } catch {\n    return res.status(401).json({ error: "Session invalide ou expiree, merci de te reconnecter." });\n  }\n}\n'
FILES['backend/src/services/email.ts'] = '// Envoi d\'email minimal. Utilisé Resend (https://resend.com, offre gratuite suffisante pour\n// un usage personnel) si RESEND_API_KEY est configuree dans les variables d\'environnement.\n// Sinon, affiche simplement le contenu dans les logs du serveur (pratique en developpement,\n// mais insuffisant en production reelle : pense a configurer RESEND_API_KEY sur Railway).\nexport async function sendEmail(to: string, subject: string, text: string): Promise<void> {\n  const apiKey = process.env.RESEND_API_KEY;\n  const from = process.env.RESEND_FROM_EMAIL || "GoTeam <onboarding@resend.dev>";\n\n  if (!apiKey) {\n    console.warn(\n      `[email] RESEND_API_KEY non configuree : email non envoye, contenu affiche ci-dessous.\\n` +\n        `[email] A: ${to}\\n[email] Sujet: ${subject}\\n[email] Corps:\\n${text}`\n    );\n    return;\n  }\n\n  try {\n    const res = await fetch("https://api.resend.com/emails", {\n      method: "POST",\n      headers: {\n        Authorization: `Bearer ${apiKey}`,\n        "Content-Type": "application/json",\n      },\n      body: JSON.stringify({ from, to, subject, text }),\n    });\n    if (!res.ok) {\n      const body = await res.text();\n      console.error("[email] Echec de l\'envoi via Resend :", res.status, body);\n    }\n  } catch (err) {\n    console.error("[email] Erreur lors de l\'envoi :", err);\n  }\n}\n'
FILES['backend/src/services/notifications.ts'] = 'import cron from "node-cron";\nimport webpush from "web-push";\nimport { prisma } from "../lib/prisma";\nimport { isDueOnDate, toDayStart, weekStart } from "../utils/recurrence";\n\n// Configure web-push avec les clés VAPID (à générer avec `npm run vapid:generate`)\nexport function initPush() {\n  const publicKey = process.env.VAPID_PUBLIC_KEY;\n  const privateKey = process.env.VAPID_PRIVATE_KEY;\n  const subject = process.env.VAPID_SUBJECT || "mailto:contact@example.com";\n\n  if (!publicKey || !privateKey) {\n    console.warn(\n      "[push] Clés VAPID manquantes : les notifications push sont désactivées. " +\n        "Génère-les avec `npm run vapid:generate` et renseigne .env"\n    );\n    return;\n  }\n  webpush.setVapidDetails(subject, publicKey, privateKey);\n  console.log("[push] Notifications push configurées.");\n}\n\n// Vérifie, pour chaque utilisateur, les exercices dus aujourd\'hui (selon la consigne du camp)\n// et pas encore faits, puis envoie une notification de rappel groupée.\nexport async function sendDailyReminders() {\n  const today = toDayStart(new Date());\n  const weekStartDate = weekStart(today);\n\n  const memberships = await prisma.campMembership.findMany({\n    include: {\n      user: { include: { subscriptions: true } },\n      camp: { include: { exercises: { include: { exercise: true } } } },\n    },\n  });\n\n  const dueByUser = new Map<string, { name: string }[]>();\n\n  for (const membership of memberships) {\n    const { camp, userId } = membership;\n    if (camp.startDate && today.getTime() < toDayStart(camp.startDate).getTime()) continue;\n    if (camp.endDate && today.getTime() > toDayStart(camp.endDate).getTime()) continue;\n\n    for (const ce of camp.exercises) {\n      if (!isDueOnDate(ce, today)) continue;\n\n      const alreadyLogged = await prisma.exerciseLog.findUnique({\n        where: {\n          userId_campId_exerciseId_date: {\n            userId,\n            campId: ce.campId,\n            exerciseId: ce.exerciseId,\n            date: today,\n          },\n        },\n      });\n      if (alreadyLogged) continue;\n\n      // Pour "X fois par semaine, n\'importe quel jour" : pas de rappel si le quota\n      // hebdomadaire est déjà atteint par un autre jour de la semaine.\n      if (ce.recurrenceType === "WEEKLY_COUNT" && ce.timesPerWeek) {\n        const weekCount = await prisma.exerciseLog.count({\n          where: { userId, campId: ce.campId, exerciseId: ce.exerciseId, date: { gte: weekStartDate, lte: today } },\n        });\n        if (weekCount >= ce.timesPerWeek) continue;\n      }\n\n      const list = dueByUser.get(userId) || [];\n      list.push({ name: ce.exercise.name });\n      dueByUser.set(userId, list);\n    }\n  }\n\n  const subscriptionsByUser = new Map(memberships.map((m) => [m.userId, m.user.subscriptions]));\n\n  for (const [userId, pending] of dueByUser) {\n    if (pending.length === 0) continue;\n    const subscriptions = subscriptionsByUser.get(userId) ?? [];\n    if (subscriptions.length === 0) continue;\n\n    const names = [...new Set(pending.map((p) => p.name))];\n    const payload = JSON.stringify({\n      title: "C\'est le moment de faire votre séance ! 💪",\n      body:\n        names.length === 1\n          ? `${names[0]} t\'attend aujourd\'hui.`\n          : `${names.slice(0, 3).join(", ")}${names.length > 3 ? "…" : ""} t\'attendent aujourd\'hui.`,\n    });\n\n    for (const sub of subscriptions) {\n      try {\n        await webpush.sendNotification(\n          { endpoint: sub.endpoint, keys: { p256dh: sub.p256dh, auth: sub.auth } },\n          payload\n        );\n      } catch (err: any) {\n        // Abonnement expiré ou invalide : on le retire\n        if (err.statusCode === 404 || err.statusCode === 410) {\n          await prisma.pushSubscription.delete({ where: { id: sub.id } }).catch(() => {});\n        } else {\n          console.error("[push] Erreur d\'envoi :", err.message);\n        }\n      }\n    }\n  }\n}\n\n// Planifie l\'envoi quotidien à l\'heure configurée (REMINDER_HOUR, défaut 18h, heure serveur)\nexport function scheduleReminders() {\n  const hour = Number(process.env.REMINDER_HOUR ?? 18);\n  const cronExpr = `0 ${hour} * * *`;\n  cron.schedule(cronExpr, () => {\n    sendDailyReminders().catch((err) => console.error("[push] Erreur lors de l\'envoi des rappels :", err));\n  });\n  console.log(`[push] Rappels quotidiens planifiés à ${hour}h (heure serveur).`);\n}\n\n// Envoie une notification à UN utilisateur précis (tous ses appareils abonnés), avec un\n// titre/corps libres. Utilisé pour prévenir d\'un nouveau message (camp ou privé).\nexport async function sendPushToUser(userId: string, title: string, body: string) {\n  const subscriptions = await prisma.pushSubscription.findMany({ where: { userId } });\n  if (subscriptions.length === 0) return;\n\n  const payload = JSON.stringify({ title, body });\n  for (const sub of subscriptions) {\n    try {\n      await webpush.sendNotification({ endpoint: sub.endpoint, keys: { p256dh: sub.p256dh, auth: sub.auth } }, payload);\n    } catch (err: any) {\n      if (err.statusCode === 404 || err.statusCode === 410) {\n        await prisma.pushSubscription.delete({ where: { id: sub.id } }).catch(() => {});\n      } else {\n        console.error("[push] Erreur d\'envoi :", err.message);\n      }\n    }\n  }\n}\n'
FILES['backend/src/utils/badges.ts'] = 'import { prisma } from "../lib/prisma";\nimport { toDayStart, isDueOnDate, computeWeeklyDueDone } from "./recurrence";\n\n// Catalogue des badges disponibles. Purement individuel : aucune comparaison entre utilisateurs.\nexport interface BadgeDefinition {\n  key: string;\n  name: string;\n  description: string;\n  emoji: string;\n}\n\nexport const BADGE_CATALOG: BadgeDefinition[] = [\n  { key: "STREAK_3", name: "3 jours d\'affilee", description: "Une séance réalisée chaque jour, 3 jours de suite.", emoji: "🔥" },\n  { key: "STREAK_7", name: "1 semaine régulière", description: "Une séance réalisée chaque jour, 7 jours de suite.", emoji: "🔥" },\n  { key: "STREAK_30", name: "1 mois de régularité", description: "Une séance réalisée chaque jour, 30 jours de suite.", emoji: "🏅" },\n  { key: "STREAK_100", name: "100 jours de suite", description: "Une séance réalisée chaque jour, 100 jours de suite.", emoji: "🏆" },\n  { key: "TOTAL_10", name: "10 séances", description: "10 séances validees au total.", emoji: "✅" },\n  { key: "TOTAL_50", name: "50 séances", description: "50 séances validees au total.", emoji: "⭐" },\n  { key: "TOTAL_100", name: "100 séances", description: "100 séances validees au total.", emoji: "🌟" },\n  { key: "TOTAL_500", name: "500 séances", description: "500 séances validees au total.", emoji: "💎" },\n  { key: "MERIT_STAR_BRONZE", name: "Étoile du mérite - Bronze", description: "Au moins 60% de tes séances prévues réalisées (sur au moins 2 semaines suivies).", emoji: "🌟" },\n  { key: "MERIT_STAR_SILVER", name: "Étoile du mérite - Argent", description: "Au moins 75% de tes séances prévues réalisées (sur au moins 2 semaines suivies).", emoji: "🌟" },\n  { key: "MERIT_STAR_GOLD", name: "Étoile du mérite - Or", description: "Au moins 90% de tes séances prévues réalisées (sur au moins 2 semaines suivies).", emoji: "🥇" },\n];\n\nconst STREAK_THRESHOLDS: [number, string][] = [\n  [100, "STREAK_100"],\n  [30, "STREAK_30"],\n  [7, "STREAK_7"],\n  [3, "STREAK_3"],\n];\n\nconst TOTAL_THRESHOLDS: [number, string][] = [\n  [500, "TOTAL_500"],\n  [100, "TOTAL_100"],\n  [50, "TOTAL_50"],\n  [10, "TOTAL_10"],\n];\n\nconst MERIT_THRESHOLDS: [number, string][] = [\n  [90, "MERIT_STAR_GOLD"],\n  [75, "MERIT_STAR_SILVER"],\n  [60, "MERIT_STAR_BRONZE"],\n];\nconst MERIT_MIN_DUE_COUNT = 14; // au moins ~2 semaines de recul avant d\'attribuer une etoile\n\n// Calcule le taux de regularite global de l\'utilisateur, tous camps confondus (uniquement\n// les camps ou il participe activement, pas ceux ou il est juste "entraineur"). Renvoie\n// null si pas assez de recul (moins de MERIT_MIN_DUE_COUNT jours/semaines dus).\nexport async function computeOverallRegularityRate(userId: string): Promise<number | null> {\n  const memberships = await prisma.campMembership.findMany({\n    where: { userId, role: { not: "COACH" } },\n    include: { camp: { include: { exercises: true, circuits: true } } },\n  });\n  if (memberships.length === 0) return null;\n\n  const restDays = await prisma.restDay.findMany({ where: { userId }, select: { date: true } });\n  const restDates = new Set(restDays.map((r) => r.date.toISOString().slice(0, 10)));\n  const today = toDayStart(new Date());\n\n  let totalDue = 0;\n  let totalDone = 0;\n\n  for (const membership of memberships) {\n    const { camp } = membership;\n    const joined = toDayStart(membership.joinedAt);\n\n    for (const ce of [...camp.exercises, ...camp.circuits]) {\n      const isCircuit = !("targetSets" in ce);\n      const logs = isCircuit\n        ? await prisma.campCircuitLog.findMany({ where: { userId, campCircuitId: (ce as any).id }, select: { date: true } })\n        : await prisma.exerciseLog.findMany({\n            where: { userId, campId: camp.id, exerciseId: (ce as any).exerciseId },\n            select: { date: true },\n          });\n      const completedDates = new Set(logs.map((l) => l.date.toISOString().slice(0, 10)));\n      const effectiveStart = toDayStart(new Date(Math.max(new Date(ce.startDate).getTime(), joined.getTime())));\n\n      if (ce.recurrenceType === "WEEKLY_COUNT" && ce.timesPerWeek) {\n        const { dueCount, doneCount } = computeWeeklyDueDone(ce.timesPerWeek, effectiveStart, completedDates, today);\n        totalDue += dueCount;\n        totalDone += doneCount;\n      } else {\n        const cursor = new Date(effectiveStart);\n        while (cursor.getTime() <= today.getTime()) {\n          const key = cursor.toISOString().slice(0, 10);\n          if (!restDates.has(key) && isDueOnDate(ce, cursor)) {\n            totalDue++;\n            if (completedDates.has(key)) totalDone++;\n          }\n          cursor.setUTCDate(cursor.getUTCDate() + 1);\n        }\n      }\n    }\n  }\n\n  if (totalDue < MERIT_MIN_DUE_COUNT) return null;\n  return Math.round((totalDone / totalDue) * 100);\n}\n\n// Calcule le plus long "streak" en cours (jours consecutifs avec au moins une séance,\n// tous camps/exercices confondus), en remontant depuis aujourd\'hui ou hier. Les jours\n// marques comme "repos justifie" sont neutres : ils n\'interrompent pas la serie.\nfunction computeGlobalStreak(distinctDates: Set<string>, today: Date, restDates: Set<string> = new Set()): number {\n  const start = toDayStart(today);\n  // Si rien n\'est fait aujourd\'hui, on tolere et on part d\'hier pour ne pas casser la serie\n  // en cours de journee.\n  let cursor = new Date(start);\n  if (!distinctDates.has(cursor.toISOString().slice(0, 10)) && !restDates.has(cursor.toISOString().slice(0, 10))) {\n    cursor.setUTCDate(cursor.getUTCDate() - 1);\n  }\n  let streak = 0;\n  for (let i = 0; i < 3650; i++) {\n    const key = cursor.toISOString().slice(0, 10);\n    if (restDates.has(key)) {\n      cursor.setUTCDate(cursor.getUTCDate() - 1);\n      continue;\n    }\n    if (!distinctDates.has(key)) break;\n    streak++;\n    cursor.setUTCDate(cursor.getUTCDate() - 1);\n  }\n  return streak;\n}\n\n// Recalcule les stats de l\'utilisateur et attribue tout nouveau badge merite.\n// Appele après chaque validation de séance (exercice, circuit de camp, ou séance chrono libre).\n// Idempotent (un badge n\'est jamais attribue deux fois).\nexport async function checkAndAwardBadges(userId: string): Promise<BadgeDefinition[]> {\n  const [exerciseLogs, circuitLogs, chronoSessions] = await Promise.all([\n    prisma.exerciseLog.findMany({ where: { userId }, select: { date: true } }),\n    prisma.campCircuitLog.findMany({ where: { userId }, select: { date: true } }),\n    prisma.chronoSession.findMany({ where: { userId }, select: { completedAt: true } }),\n  ]);\n\n  const distinctDates = new Set<string>([\n    ...exerciseLogs.map((l) => l.date.toISOString().slice(0, 10)),\n    ...circuitLogs.map((l) => l.date.toISOString().slice(0, 10)),\n    ...chronoSessions.map((s) => s.completedAt.toISOString().slice(0, 10)),\n  ]);\n  const totalSessions = exerciseLogs.length + circuitLogs.length + chronoSessions.length;\n  const restDays = await prisma.restDay.findMany({ where: { userId }, select: { date: true } });\n  const restDates = new Set(restDays.map((r) => r.date.toISOString().slice(0, 10)));\n  const streak = computeGlobalStreak(distinctDates, new Date(), restDates);\n\n  const earnedKeys = new Set<string>();\n  // On attribue TOUS les paliers déjà franchis (pas seulement le plus haut), pour garder\n  // l\'historique des badges obtenus même si la serie casse ensuite.\n  for (const [threshold, key] of STREAK_THRESHOLDS) {\n    if (streak >= threshold) earnedKeys.add(key);\n  }\n  for (const [threshold, key] of TOTAL_THRESHOLDS) {\n    if (totalSessions >= threshold) earnedKeys.add(key);\n  }\n\n  const overallRate = await computeOverallRegularityRate(userId);\n  if (overallRate !== null) {\n    for (const [threshold, key] of MERIT_THRESHOLDS) {\n      if (overallRate >= threshold) earnedKeys.add(key);\n    }\n  }\n\n  if (earnedKeys.size === 0) return [];\n\n  const alreadyEarned = await prisma.userBadge.findMany({ where: { userId }, select: { badgeKey: true } });\n  const alreadyEarnedKeys = new Set(alreadyEarned.map((b) => b.badgeKey));\n\n  const newlyEarned = [...earnedKeys].filter((k) => !alreadyEarnedKeys.has(k));\n  if (newlyEarned.length === 0) return [];\n\n  await prisma.userBadge.createMany({\n    data: newlyEarned.map((badgeKey) => ({ userId, badgeKey })),\n  });\n\n  return BADGE_CATALOG.filter((b) => newlyEarned.includes(b.key));\n}\n'
FILES['backend/src/utils/code.ts'] = '// Généré un code court, lisible a l\'oral, pour rejoindre un camp.\n// On evite les caractères ambigus (0/O, 1/I/L) pour limiter les erreurs de saisie.\nconst ALPHABET = "ABCDEFGHJKMNPQRSTUVWXYZ23456789";\n\nexport function generateCampCode(length = 6): string {\n  let code = "";\n  for (let i = 0; i < length; i++) {\n    code += ALPHABET[Math.floor(Math.random() * ALPHABET.length)];\n  }\n  return code;\n}\n'
FILES['backend/src/utils/equipment.ts'] = 'export const EQUIPMENT_CATALOG = [\n  { key: "AUCUN", label: "Aucun materiel (poids du corps)" },\n  { key: "HALTERES", label: "Halteres / poids libres" },\n  { key: "BARRE_TRACTION", label: "Barre de traction" },\n  { key: "ELASTIQUE", label: "Elastique de resistance" },\n  { key: "BANC", label: "Banc de musculation" },\n  { key: "KETTLEBELL", label: "Kettlebell" },\n  { key: "CORDE_A_SAUTER", label: "Corde a sauter" },\n  { key: "TAPIS", label: "Tapis de sol" },\n  { key: "VELO", label: "Velo / home trainer" },\n  { key: "AUTRE", label: "Autre materiel specifique" },\n];\n\nexport const EQUIPMENT_KEYS = EQUIPMENT_CATALOG.map((e) => e.key);\n'
FILES['backend/src/utils/reactions.ts'] = 'export interface ReactionDefinition {\n  key: string;\n  label: string;\n  emoji: string;\n}\n\n// Inspire des chants/rituels de supporters : encourager, pas comparer les performances.\nexport const REACTION_CATALOG: ReactionDefinition[] = [\n  { key: "OVATION", label: "Ovation", emoji: "🙌" },\n  { key: "RESPECT", label: "Respect", emoji: "🫡" },\n  { key: "HAKA", label: "Haka", emoji: "💥" },\n  { key: "OLA", label: "Ola", emoji: "🌊" },\n  { key: "HYMNE", label: "Hymne", emoji: "🎶" },\n  { key: "CLAPPING", label: "Clapping", emoji: "👏" },\n  { key: "TIFO", label: "Tifo", emoji: "🎨" },\n  { key: "TAMBOURINAGE", label: "Tambourinage", emoji: "🥁" },\n];\n\nexport const REACTION_KEYS = REACTION_CATALOG.map((r) => r.key);\n'
FILES['backend/src/utils/recurrence.ts'] = '// Logique de récurrence : détermine si un programme (exercice + planning)\n// est "dû" un jour donné, indépendamment du fait qu\'il ait été fait ou non.\n\n// Remarque : type assoupli en "string" (plutôt qu\'une union littérale stricte) car le champ\n// correspondant dans la base (voir schema.prisma) est un simple String -- SQLite ne supporte\n// pas les enums natifs. La validation des valeurs autorisées se fait côté API avec zod.\nexport type RecurrenceType = string;\n\nexport interface RecurrenceInput {\n  recurrenceType: RecurrenceType;\n  daysOfWeek?: string | null; // JSON string ex: "[1,3,5]"\n  intervalDays?: number | null;\n  timesPerWeek?: number | null; // utilisé si WEEKLY_COUNT\n  startDate: Date;\n}\n\n// Normalise une date à minuit (UTC) pour comparer uniquement les jours calendaires\nexport function toDayStart(d: Date): Date {\n  const copy = new Date(d);\n  copy.setUTCHours(0, 0, 0, 0);\n  return copy;\n}\n\nexport function daysBetween(a: Date, b: Date): number {\n  const MS_PER_DAY = 24 * 60 * 60 * 1000;\n  return Math.round((toDayStart(b).getTime() - toDayStart(a).getTime()) / MS_PER_DAY);\n}\n\n// Retourne le lundi (début de semaine) de la semaine contenant `date`\nexport function weekStart(date: Date): Date {\n  const d = toDayStart(date);\n  const day = d.getUTCDay(); // 0=dimanche, 1=lundi, ..., 6=samedi\n  const diff = day === 0 ? -6 : 1 - day;\n  d.setUTCDate(d.getUTCDate() + diff);\n  return d;\n}\n\nexport function isDueOnDate(program: RecurrenceInput, date: Date): boolean {\n  const day = toDayStart(date);\n  const start = toDayStart(program.startDate);\n\n  // Un programme n\'est jamais "dû" avant sa date de création\n  if (day.getTime() < start.getTime()) return false;\n\n  switch (program.recurrenceType) {\n    case "DAILY":\n      return true;\n\n    case "WEEKLY": {\n      const days: number[] = program.daysOfWeek ? JSON.parse(program.daysOfWeek) : [];\n      return days.includes(day.getUTCDay());\n    }\n\n    case "EVERY_N_DAYS": {\n      const interval = program.intervalDays && program.intervalDays > 0 ? program.intervalDays : 1;\n      const diff = daysBetween(start, day);\n      return diff % interval === 0;\n    }\n\n    case "WEEKLY_COUNT":\n      // "X fois par semaine, n\'importe quel jour" : tous les jours sont candidats,\n      // c\'est au niveau de l\'affichage (voir today.ts) qu\'on masque une fois le quota\n      // hebdomadaire atteint.\n      return true;\n\n    default:\n      return false;\n  }\n}\n\n// Calcule la "régularité" (streak) : nombre de jours consécutifs (en remontant depuis aujourd\'hui)\n// où l\'exercice était dû et a bien été complété. On s\'arrête au premier jour de manque.\n// Les jours marqués comme "repos justifié" (restDates) sont neutres : ni un manque, ni une réussite,\n// ils n\'interrompent pas la série. Ne s\'applique pas au type WEEKLY_COUNT (voir computeWeeklyStreak).\nexport function computeStreak(\n  program: RecurrenceInput,\n  completedDates: Set<string>, // dates au format YYYY-MM-DD où l\'exercice a été complété\n  today: Date,\n  restDates: Set<string> = new Set()\n): number {\n  let streak = 0;\n  const cursor = toDayStart(today);\n\n  // On remonte jour par jour, en ignorant les jours où l\'exercice n\'était pas prévu\n  // mais en cassant la série dès qu\'un jour prévu n\'a pas été fait (sauf jour de repos justifié).\n  for (let i = 0; i < 3650; i++) {\n    const d = new Date(cursor);\n    d.setUTCDate(d.getUTCDate() - i);\n    if (d.getTime() < toDayStart(program.startDate).getTime()) break;\n\n    const key = d.toISOString().slice(0, 10);\n    if (restDates.has(key)) continue; // jour neutre, on passe au suivant sans casser la série\n\n    if (isDueOnDate(program, d)) {\n      if (completedDates.has(key)) {\n        streak++;\n      } else {\n        // Si c\'est aujourd\'hui et pas encore fait, on ne casse pas la série\n        // (la journée n\'est pas terminée), on continue juste sans incrémenter.\n        if (i === 0) continue;\n        break;\n      }\n    }\n  }\n  return streak;\n}\n\n// Compte le nombre de completions dans la semaine commençant à `ws` (lundi), en ne\n// regardant pas au-delà d\'aujourd\'hui.\nfunction countInWeek(ws: Date, completedDates: Set<string>, today: Date): number {\n  let count = 0;\n  const todayStart = toDayStart(today);\n  for (let i = 0; i < 7; i++) {\n    const d = new Date(ws);\n    d.setUTCDate(d.getUTCDate() + i);\n    if (d.getTime() > todayStart.getTime()) break;\n    if (completedDates.has(d.toISOString().slice(0, 10))) count++;\n  }\n  return count;\n}\n\n// Équivalent de dueCount/doneCount mais à la semaine (pour le type WEEKLY_COUNT) :\n// chaque semaine écoulée depuis le début du programme est une unité "due", réussie si\n// le nombre de séances cette semaine-là atteint le quota fixé.\nexport function computeWeeklyDueDone(\n  timesPerWeek: number,\n  startDate: Date,\n  completedDates: Set<string>,\n  today: Date\n): { dueCount: number; doneCount: number } {\n  const start = weekStart(startDate);\n  const currentWeekStart = weekStart(today);\n  let dueCount = 0;\n  let doneCount = 0;\n  const cursor = new Date(start);\n  while (cursor.getTime() <= currentWeekStart.getTime()) {\n    dueCount++;\n    if (countInWeek(cursor, completedDates, today) >= timesPerWeek) doneCount++;\n    cursor.setUTCDate(cursor.getUTCDate() + 7);\n  }\n  return { dueCount, doneCount };\n}\n\n// Nombre de semaines consécutives (en remontant depuis la semaine courante) où le quota\n// hebdomadaire a été atteint. La semaine en cours n\'est jamais considérée comme "cassée"\n// tant qu\'elle n\'est pas terminée : si le quota n\'est pas encore atteint, on l\'ignore\n// simplement (elle ne compte pas encore, mais ne casse rien) et on regarde la précédente.\nexport function computeWeeklyStreak(\n  timesPerWeek: number,\n  startDate: Date,\n  completedDates: Set<string>,\n  today: Date\n): number {\n  const currentWeekStart = weekStart(today);\n  const startWeek = weekStart(startDate);\n  let streak = 0;\n  let cursor = new Date(currentWeekStart);\n\n  if (countInWeek(cursor, completedDates, today) >= timesPerWeek) {\n    streak++;\n  }\n  cursor.setUTCDate(cursor.getUTCDate() - 7);\n\n  for (let i = 0; i < 520; i++) {\n    if (cursor.getTime() < startWeek.getTime()) break;\n    if (countInWeek(cursor, completedDates, today) >= timesPerWeek) {\n      streak++;\n      cursor.setUTCDate(cursor.getUTCDate() - 7);\n    } else {\n      break;\n    }\n  }\n  return streak;\n}\n'

